import json,sys,urllib.request,urllib.error
value=json.load(sys.stdin)
origin='http://localhost:8080'
headers={'Origin':origin}
data=None
if value['payload'] is not None:
    headers['Content-Type']='application/json'
    data=json.dumps(value['payload']).encode()
if value['credentials']:
    headers.update({'Cookie':'dw-local-session='+value['credentials'][0],'X-CSRF-Token':value['credentials'][1]})
request=urllib.request.Request(origin+value['path'],data=data,headers=headers,method=value['method'])
client=urllib.request.build_opener(urllib.request.ProxyHandler({}))
try:response=client.open(request,timeout=10)
except urllib.error.HTTPError as error:response=error
raw=response.read()
try:body=json.loads(raw)
except ValueError:body={}
print(json.dumps({'status':response.status,'body':body,'headers':list(response.headers.items())}))

